INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('home.eyebrow','home','Artista plástico / Huánuco');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('home.title','home','Capturando la esencia en cada trazo.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('home.titleAccent','home','esencia');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('home.subtitle','home','Murales, esculturas y proyectos integrales que transforman espacios con la maestría del realismo.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('profile.tagline','profile','Talento que trasciende fronteras.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('profile.specialties','profile','Murales · Escultura · Realismo');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('archive.eyebrow','archive','Archivo visual');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('archive.title','archive','Obras con historia.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('archive.titleAccent','archive','historia');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('archive.subtitle','archive','Una selección de proyectos que encuentran su lugar en el mundo.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('about.photoCaption','about','El oficio, en cada detalle');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('about.eyebrow','about','Una práctica con propósito');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('about.title','about','Arte hecho con identidad.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('about.titleAccent','about','identidad');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('about.description','about','Cada proyecto nace de una idea y de la conversación con quienes habitan el espacio. Conoce nuestra propuesta artística y conversemos sobre lo que te gustaría crear.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('contact.eyebrow','contact','Hablemos de tu idea');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('contact.title','contact','Todo gran proyecto empieza con una conversación.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('contact.description','contact','Cuéntanos qué tienes en mente. Te ayudaremos a encontrar la mejor forma de llevarlo a la realidad.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.mural.subtitle','services','Historias en grandes muros');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.mural.description','services','Arte que transforma muros en relatos vivos. Composiciones originales, pensadas para dialogar con su espacio y su gente.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.escultura.subtitle','services','Forma que respira');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.escultura.description','services','Volumen, materia y carácter se encuentran en piezas únicas, creadas para habitar espacios con presencia y sensibilidad.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.cuadro.subtitle','services','Tu historia, enmarcada');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.cuadro.description','services','Retratos y obras hechas a medida que conservan lo esencial: una historia, una emoción, una forma propia de mirar.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.restauracion.subtitle','services','Memoria que perdura');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.restauracion.description','services','Cuidado experto para recuperar la fuerza y el detalle de obras, superficies y espacios con valor artístico y afectivo.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.logo.subtitle','services','Tu marca, a gran escala');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.logo.description','services','Identidad visual pintada a mano para marcas que quieren hacerse ver. Diseño, precisión y oficio en cada trazo.');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.fachada.subtitle','services','Identidad en cada muro');
INSERT OR IGNORE INTO textos(clave,grupo,valor) VALUES ('service.fachada.description','services','Una nueva mirada para la fachada de tu negocio o vivienda, con color, intención y una ejecución hecha para durar.');
